package cn.ngapure.app;
import android.content.Context;import java.lang.reflect.Field;import java.util.ArrayList;import java.util.List;import java.util.concurrent.CountDownLatch;import java.util.concurrent.ExecutorService;import java.util.concurrent.TimeUnit;import java.util.concurrent.ThreadPoolExecutor;
/** Observable task/session contract; never inspects the coalescer fields or copies its decisions. */
public final class CheckInOpenQueueTest {
 private static final Context CONTEXT=new Context();private static final NgaStore.CheckInSession A=session("bbs.nga.cn","123","cookie-a");private static ExecutorService worker;private static int checks,scenarios;
 private static NgaStore.CheckInSession session(String host,String account,String cookie){return new NgaStore.CheckInSession(host,account,cookie);}
 private static void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
 private static void await(CountDownLatch latch,String label)throws Exception{check(latch.await(2,TimeUnit.SECONDS),label);}
 private static int queuedTasks()throws Exception{Object current=worker;for(int depth=0;depth<4;depth++){if(current instanceof ThreadPoolExecutor)return ((ThreadPoolExecutor)current).getQueue().size();Field nested=null;for(Class<?> type=current.getClass();type!=null&&nested==null;type=type.getSuperclass())for(Field f:type.getDeclaredFields())if(ExecutorService.class.isAssignableFrom(f.getType())){nested=f;break;}if(nested==null)throw new IllegalStateException("No generic executor delegate found");nested.setAccessible(true);current=nested.get(current);}throw new IllegalStateException("Unexpected executor wrapping depth");}
 private static void settle()throws Exception{for(int i=0;i<3;i++){worker.submit(()->{}).get(3,TimeUnit.SECONDS);Thread.sleep(20);}}
 private static void reset()throws Exception{settle();NgaStore.current=A;NgaStore.enabled=true;NgaStore.afterDayRead=null;NgaStore.dayHookCountdown=1;NgaStore.confirmedDay="";NgaStore.confirmedAccount="";NgaStore.clockDay="synthetic-day";NgaStore.captures.set(0);NgaStore.loginReads.set(0);NgaApi.reset();scenarios++;}
 private static void request(NgaStore.CheckInSession scope,int count){NgaStore.current=scope;for(int i=0;i<count;i++)CheckInService.checkOnOpen(CONTEXT);}
 private static boolean same(NgaStore.CheckInSession a,NgaStore.CheckInSession b){return a.host.equals(b.host)&&a.account.equals(b.account)&&a.cookie.equals(b.cookie);}
 private static void sameScopeBurstAndLaterRetry()throws Exception{reset();NgaApi.Gate first=NgaApi.gate(true);request(A,1);await(first.started,"First synthetic attempt started");request(A,64);check(queuedTasks()==0,"Same-session trigger burst queues no additional foreground tasks while active");check(NgaApi.count()==1,"A pending foreground check-in does not start concurrent writes");first.release.countDown();settle();check(NgaApi.count()==1,"65 identical pending foreground triggers do not replay failures");check(NgaApi.interrupted.get()==0,"Coalescing never interrupts an already submitted write");NgaApi.Gate later=NgaApi.gate(false);request(A,1);await(later.started,"A later deliberate foreground event is accepted after settlement");settle();check(NgaApi.count()==2,"A completed failure does not permanently block later foreground attempts");}
 private static void switches(String type,NgaStore.CheckInSession b)throws Exception{reset();NgaApi.Gate first=NgaApi.gate(true),follow=NgaApi.gate(true);request(A,1);await(first.started,type+" old scope starts");request(b,65);check(queuedTasks()==0,type+" latest session stays in one slot rather than an executor backlog");check(NgaApi.count()==1,type+" new scope waits for old write settlement");first.release.countDown();await(follow.started,type+" latest exact scope is retained");check(NgaApi.count()==2&&same(NgaApi.at(0),A)&&same(NgaApi.at(1),b),type+" one followup uses the requested exact session");request(b,64);follow.release.countDown();settle();check(NgaApi.count()==2,type+" same new scope bursts stay coalesced");check(NgaApi.interrupted.get()==0,type+" no confirmed write is canceled");}
 private static void newestWins()throws Exception{reset();NgaApi.Gate first=NgaApi.gate(true),last=NgaApi.gate(false);NgaStore.CheckInSession b=session("bbs.nga.cn","456","cookie-b"),c=session("ngabbs.com","456","cookie-c"),d=session("ngabbs.com","456","cookie-d");request(A,1);await(first.started,"A starts before multiple session switches");request(b,20);request(c,20);request(d,20);first.release.countDown();await(last.started,"Latest D scope eventually starts");settle();check(NgaApi.count()==2&&same(NgaApi.at(1),d),"A→B→C→D retains only D instead of stale queued identities");}
 private static void returnsToCurrent()throws Exception{reset();NgaApi.Gate first=NgaApi.gate(true);request(A,1);await(first.started,"A starts before transient session switch");request(session("bbs.nga.cn","456","cookie-b"),32);request(A,32);first.release.countDown();settle();check(NgaApi.count()==1,"A→B→A does not replay the same already attempted exact A session");}
 private static CountDownLatch blockQueue()throws Exception{CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);worker.submit(()->{entered.countDown();try{release.await(3,TimeUnit.SECONDS);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}});await(entered,"Synthetic unrelated worker task starts");return release;}
 private static void queuedNewest()throws Exception{reset();CountDownLatch release=blockQueue();NgaStore.CheckInSession b=session("ngabbs.com","456","cookie-b");NgaApi.Gate only=NgaApi.gate(false);request(A,32);request(b,32);check(queuedTasks()==1,"Before execution, foreground scheduling owns exactly one queued runnable");check(NgaApi.count()==0,"Queued foreground reads have not bypassed existing worker ownership");release.countDown();await(only.started,"Queued newest scope starts after prior work");settle();check(NgaApi.count()==1&&same(NgaApi.at(0),b),"Before execution, latest session replaces the queued old session without adding work");}
 private static void staleQueuedScope()throws Exception{reset();CountDownLatch release=blockQueue();request(A,1);NgaStore.current=session("bbs.nga.cn","456","cookie-b");release.countDown();settle();check(NgaApi.count()==0,"An unrequested newer session never inherits a queued old-session task");NgaApi.Gate current=NgaApi.gate(false);request(NgaStore.current,1);await(current.started,"Explicit current-session foreground request still works");settle();check(NgaApi.count()==1,"Stale queued task releases the coalescer for current session");}
 private static void disabledWhileQueued()throws Exception{reset();CountDownLatch release=blockQueue();request(A,65);NgaStore.enabled=false;release.countDown();settle();check(NgaApi.count()==0,"Disabling automatic check-in before execution prevents every queued network attempt");NgaStore.enabled=true;NgaApi.Gate current=NgaApi.gate(false);request(A,1);await(current.started,"Reenabled automatic check-in accepts a later foreground event");settle();check(NgaApi.count()==1,"Disabled queued task does not poison future scheduling");}
 private static void changedBetweenServiceCheckAndApi(String type,NgaStore.CheckInSession b)throws Exception{reset();CountDownLatch release=blockQueue();request(A,1);NgaStore.dayHookCountdown=2;NgaStore.afterDayRead=()->NgaStore.current=b;release.countDown();settle();check(NgaApi.count()==0,type+" switching after Service scope check never signs in an unrequested new scope");NgaApi.Gate current=NgaApi.gate(false);request(b,1);await(current.started,type+" newer scope still accepts its explicit foreground trigger");settle();check(NgaApi.count()==1&&same(NgaApi.at(0),b),type+" immutable expected session reaches API rather than a mutable recapture");}
 private static void concurrentBurst()throws Exception{reset();NgaApi.Gate first=NgaApi.gate(true);request(A,1);await(first.started,"A starts before concurrent foreground triggers");List<Thread> threads=new ArrayList<>();for(int i=0;i<8;i++){Thread thread=new Thread(()->request(A,32),"SyntheticForeground");threads.add(thread);thread.start();}for(Thread thread:threads){thread.join(2000);check(!thread.isAlive(),"Concurrent foreground enqueue remains nonblocking");}check(queuedTasks()==0,"Concurrent pending triggers never grow the executor queue");first.release.countDown();settle();check(NgaApi.count()==1,"257 concurrent same-session foreground triggers remain one attempt");check(NgaApi.interrupted.get()==0,"Concurrent enqueue never interrupts the active write");}
 private static void completedDaySkipsCredentials()throws Exception{
  reset();NgaStore.confirmed();int schedules=CONTEXT.jobs.schedules.get();request(A,65);settle();
  check(CONTEXT.jobs.schedules.get()==schedules+65,"Already-confirmed day still reconciles the OS schedule for every explicit trigger");
  check(NgaStore.captures.get()==0&&NgaStore.loginReads.get()==0,"Already-confirmed foreground day performs no credential capture or login resolution");
  check(NgaApi.count()==0&&queuedTasks()==0,"Already-confirmed foreground burst queues no HTTP work");
 }
 private static void completedAfterQueued()throws Exception{
  reset();CountDownLatch release=blockQueue();request(A,1);int captures=NgaStore.captures.get();NgaStore.confirmed();release.countDown();settle();
  check(NgaStore.captures.get()==captures&&NgaStore.loginReads.get()==0&&NgaApi.count()==0,"Confirmation after enqueue skips both drain recapture and perform login work");
  NgaStore.clockDay="synthetic-next-day";request(A,1);settle();check(NgaApi.count()==1,"Skipped confirmed queue releases ownership for next-day foreground request");
 }
 private static void completedBeforePerform()throws Exception{
  reset();CountDownLatch release=blockQueue();request(A,1);NgaStore.afterDayRead=NgaStore::confirmed;release.countDown();settle();
  check(NgaStore.captures.get()==2&&NgaStore.loginReads.get()==0&&NgaApi.count()==0,"Confirmation after drain day observation is rechecked before perform login work");
 }
 private static void scheduledConfirmedDay()throws Exception{
  reset();NgaStore.confirmed();CheckInService service=new CheckInService();check(service.onStartJob(new android.app.job.JobParameters()),"Scheduled job still completes asynchronously");settle();
  check(NgaStore.captures.get()==0&&NgaStore.loginReads.get()==0&&NgaApi.count()==0,"Already-confirmed background job avoids login and HTTP work");
 }
 private static void nextDayAndAccount()throws Exception{
  reset();NgaStore.confirmed();request(A,1);settle();check(NgaApi.count()==0,"Current confirmed day is skipped");
  NgaStore.clockDay="synthetic-next-day";request(A,1);settle();check(NgaApi.count()==1,"Following date still executes the same account");
  NgaStore.confirmed();NgaStore.CheckInSession b=session("bbs.nga.cn","456","cookie-b");request(b,1);settle();check(NgaApi.count()==2&&same(NgaApi.at(1),b),"Different account does not inherit the previous account completion day");
  NgaStore.confirmed();int before=NgaStore.captures.get();request(session("bbs.nga.cn","456","cookie-renewed"),1);settle();check(NgaApi.count()==2&&NgaStore.captures.get()==before,"Same-account token renewal retains the existing confirmed-day policy");
 }
 private static void midnightDuringDayRead()throws Exception{
  reset();NgaStore.confirmed();NgaStore.afterDayRead=()->NgaStore.clockDay="synthetic-next-day";request(A,1);settle();
  check(NgaApi.count()==1,"Midnight crossed while reading saved day does not suppress the new date");
 }
 private static void switchAfterConfirmedObservation()throws Exception{
  reset();NgaStore.confirmed();NgaStore.CheckInSession b=session("bbs.nga.cn","456","cookie-b");NgaStore.afterDayRead=()->NgaStore.current=b;CheckInService.checkOnOpen(CONTEXT);settle();
  check(NgaApi.count()==0&&NgaStore.captures.get()==0,"Confirmed old-account observation never starts an unrequested replacement-account task");
  request(b,1);settle();check(NgaApi.count()==1&&same(NgaApi.at(0),b),"Replacement account explicit foreground trigger remains eligible");
 }
 public static void main(String[] args)throws Exception{Field field=CheckInService.class.getDeclaredField("WORKER");field.setAccessible(true);worker=(ExecutorService)field.get(null);try{sameScopeBurstAndLaterRetry();switches("account",session("bbs.nga.cn","456","cookie-b"));switches("host",session("ngabbs.com","123","cookie-a"));switches("cookie",session("bbs.nga.cn","123","cookie-new"));newestWins();returnsToCurrent();queuedNewest();staleQueuedScope();disabledWhileQueued();changedBetweenServiceCheckAndApi("account",session("bbs.nga.cn","456","cookie-b"));changedBetweenServiceCheckAndApi("host",session("ngabbs.com","123","cookie-a"));changedBetweenServiceCheckAndApi("cookie",session("bbs.nga.cn","123","cookie-new"));concurrentBurst();completedDaySkipsCredentials();completedAfterQueued();completedBeforePerform();scheduledConfirmedDay();nextDayAndAccount();midnightDuringDayRead();switchAfterConfirmedObservation();System.out.println("{\"passed\":true,\"scenarios\":"+scenarios+",\"checks\":"+checks+",\"productionServiceSourceUsed\":true,\"syntheticSessionBoundaries\":true,\"realNetworkRequests\":0,\"realCheckInWrites\":0}");}finally{worker.shutdownNow();}}
}
